public class NightRecoverOwnedServer extends StarMacro {public void execute(){Simulation s=getActiveSimulation();Path d=Paths.get(System.getenv("MINI_CASE_DIR"));try{String path=s.getSessionPath().replace('\\','/');if(!path.startsWith("F:/ntnu/flap_control/exploration_lab/MINI_POC_2D_20261103/mini_vof_20261103/"))throw new IllegalStateException("Not owned MiniVOF case");if(((FvRepresentation)s.getRepresentationManager().getObject("Volume Mesh")).getCellCount()!=41280 && ((FvRepresentation)s.getRepresentationManager().getObject("Volume Mesh")).getCellCount()!=44442)throw new IllegalStateException("Unexpected mesh");s.getSimulationIterator().stop();Path p=d.resolve("INTERRUPTED_INNER_NOT_VALIDATED.sim");if(Files.exists(p))throw new IllegalStateException("No checkpoint overwrite");s.saveState(p.toString());Files.writeString(d.resolve("RECOVERY.json"),"{\"checkpoint\":\""+p.toString().replace('\\','/')+"\",\"bytes\":"+Files.size(p)+",\"physical_time\":"+s.getSolution().getPhysicalTime()+",\"accepted\":false,\"reason\":\"Client disconnect during inner iterations; diagnostic preservation only\",\"force_termination\":false,\"supported_close_requested\":true}");s.close(ServerConnection.CloseOption.Close);}catch(Exception e){throw new RuntimeException(e);}}}
